import{_ as a,o as i,c as s,ak as d}from"./chunks/framework.DIgTxpuq.js";const k=JSON.parse('{"title":"Dice","description":"","frontmatter":{},"headers":[],"relativePath":"guide/notation/dice.md","filePath":"guide/notation/dice.md","lastUpdated":1794009813000}'),t={name:"guide/notation/dice.md"};function n(o,e,l,c,p,r){return i(),s("div",null,[...e[0]||(e[0]=[d('<h1 id="dice" tabindex="-1">Dice <a class="header-anchor" href="#dice" aria-label="Permalink to &quot;Dice&quot;">​</a></h1><p>The simplest form of notation is just a basic dice roll.</p><div class="warning custom-block"><p class="custom-block-title">Die quantity</p><p>A single die has a minimum quantity of <code>1</code>, and a maximum quantity of <code>999</code>.</p><p>✅ These are valid: <code>d8</code>, <code>1d10</code>, <code>999d6</code>, <code>20d4 + 999d10</code>.</p><p>❌ These are not: <code>0d10</code>, <code>1000d6</code>, <code>-1d20</code>.</p></div><h2 id="standard" tabindex="-1">Standard <a class="header-anchor" href="#standard" aria-label="Permalink to &quot;Standard&quot;">​</a></h2><p><strong>Notation:</strong> <code>d{n}</code></p><p>A standard die has a positive numerical number of sides, like typical 6 sided dice, or a d20.</p><p>You can roll dice with almost any number of sides.</p><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d6    </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// roll a single 6 sided dice</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">4d10  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// roll a 10 sided dice 4 times and add the results together</span></span></code></pre></div><p>::: roller 4d10 :::</p><h2 id="percentile-dice" tabindex="-1">Percentile dice <a class="header-anchor" href="#percentile-dice" aria-label="Permalink to &quot;Percentile dice&quot;">​</a></h2><p><strong>Notation:</strong> <code>d%</code></p><p>Percentile dice roll a whole number between <code>1-100</code>, and are specified with the format <code>d%</code>. This is a shorthand for a standard die with 100 sides, <code>d100</code></p><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">4d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">%</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  // roll a percentile die 4 times and add the results together</span></span></code></pre></div><p>Is equivalent to:</p><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">4d100  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// roll a 100 sided die 4 times and add the results together</span></span></code></pre></div><p>::: roller 4d% :::</p><h2 id="fudge-fate-dice" tabindex="-1">Fudge / Fate dice <a class="header-anchor" href="#fudge-fate-dice" aria-label="Permalink to &quot;Fudge / Fate dice&quot;">​</a></h2><p><strong>Notation:</strong> <code>dF</code> / <code>dF.2</code> / <code>dF.1</code></p><p>Fudge dice are 6 sided dice marked with minus (<code>-</code>), plus (<code>+</code>), and blank sides, which correlate to <code>-1</code>, <code>+1</code>, and <code>0</code> respectively.</p><p>The default is one third of each, known as <code>dF.2</code>, or just <code>dF</code>. A variant is <code>dF.1</code> which has 4 blanks, 1 plus, and 1 minus.</p><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">dF    </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// roll a standard Fudge die. Equivalent to `dF.2`</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">dF.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  // roll a standard Fudge dice. Equivalent to `dF`</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">dF.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  // roll the variant Fudge dice</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">4dF   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Roll a standard Fudge die 4 times and add the results together</span></span></code></pre></div><p>::: roller 4dF :::</p>',22)])])}const u=a(t,[["render",n]]);export{k as __pageData,u as default};
